export function ProfilePage() {
  const [cartOpen, setCartOpen] = useState(false);
  const { user, accessToken, setUser } = useAuth();
  const [displayName, setDisplayName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [orderCount, setOrderCount] = useState(0);
  const [spent, setSpent] = useState(0);
  const [saveErr, setSaveErr] = useState("");
  const [saveOk, setSaveOk] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!accessToken) {
      setDisplayName("");
      setEmail("");
      setPhone("");
      setOrderCount(0);
      setSpent(0);
      return;
    }
    let cancelled = false;
    apiFetch("/api/auth/me", { headers: { Authorization: `Bearer ${accessToken}` } })
      .then((d) => {
        if (cancelled || !d.user) return;
        setDisplayName(d.user.displayName || "");
        setEmail(d.user.email || "");
        setPhone(d.user.phone || "");
      })
      .catch(() => {});
    apiFetch("/api/orders", { headers: { Authorization: `Bearer ${accessToken}` } })
      .then((d) => {
        if (cancelled) return;
        const list = d.orders || [];
        setOrderCount(list.length);
        const paid = list.filter((o) => ["paid", "processing", "shipped", "delivered"].includes(o.status));
        setSpent(paid.reduce((s, o) => s + Number(o.total || 0), 0));
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [accessToken]);

  const saveProfile = async () => {
    setSaveErr("");
    setSaveOk("");
    if (!accessToken) return;
    setSaving(true);
    try {
      const data = await apiFetch("/api/auth/profile", {
        method: "PATCH",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: { displayName: displayName.trim(), phone: phone.trim() }
      });
      if (data.user) setUser(data.user);
      setSaveOk("Profile updated.");
    } catch (ex) {
      setSaveErr(ex.message || "Save failed");
    } finally {
      setSaving(false);
    }
  };

  return h("div", { className: "min-h-screen" }, [
    h(BuyerHeader, { onOpenCart: () => setCartOpen(true), hideSearch: true }),
    h("div", { className: "mx-auto max-w-3xl px-4 py-10 sm:px-6" }, [
      h("div", { className: "mb-8 flex flex-col items-center text-center" }, [
        h(RefImage, { n: 12, alt: "Profile", className: "h-24 w-24 rounded-full object-cover ring-4 ring-sky-500/30" }),
        h(
          "h1",
          { className: "mt-4 font-display text-2xl font-bold text-slate-900 dark:text-white" },
          displayName || user?.displayName || user?.email || "Your profile"
        ),
        h("p", { className: "text-sm text-slate-500 dark:text-slate-400" }, user?.email || "Sign in to sync your account")
      ]),
      h(GlassPanel, { className: "mb-6" }, [
        h("h2", { className: "text-lg font-semibold text-slate-900 dark:text-white" }, "Account details"),
        h("div", { className: "mt-4 space-y-4" }, [
          h(Field, { label: "Display name" }, h(TextInput, { value: displayName, onChange: (e) => setDisplayName(e.target.value), placeholder: "Your name" })),
          h(Field, { label: "Email" }, h(TextInput, { type: "email", value: email, disabled: true })),
          h(Field, { label: "Phone" }, h(TextInput, { value: phone, onChange: (e) => setPhone(e.target.value), placeholder: "+1 …" })),
          saveErr && h("p", { className: "text-sm text-rose-400" }, saveErr),
          saveOk && h("p", { className: "text-sm text-emerald-400" }, saveOk),
          h(
            Button,
            {
              variant: "primary",
              className: "w-full sm:w-auto",
              type: "button",
              onClick: saveProfile,
              loading: saving,
              disabled: !accessToken
            },
            "Save changes"
          ),
          !accessToken &&
            h("p", { className: "text-sm text-amber-400" }, "You are browsing as a guest. Log in to persist profile changes.")
        ])
      ]),
      h(GlassCard, {}, h("div", { className: "grid grid-cols-2 gap-4 text-center sm:grid-cols-3" }, [
        h("div", {}, [
          h("p", { className: "text-2xl font-bold text-slate-900 dark:text-white" }, String(orderCount)),
          h("p", { className: "text-xs text-slate-500 dark:text-slate-400" }, "Orders")
        ]),
        h("div", { className: "sm:col-span-1" }, [
          h("p", { className: "text-2xl font-bold text-slate-900 dark:text-white" }, `$${spent.toFixed(2)}`),
          h("p", { className: "text-xs text-slate-500 dark:text-slate-400" }, "Spent (paid orders)")
        ])
      ]))
    ]),
    h(CartDrawer, { open: cartOpen, onClose: () => setCartOpen(false) })
  ]);
}

